export const shoePaperSources={historyShoePaper:'shoe-paper-texture-v56.png'};
export const shoePaperDefaults={historyShoePaperEnabled:true,historyPaperShoeMode:'auto',historyShoeTurnStart:32,historyShoeTurnEnd:38.849,historyShoeTiltEnd:.24,historyShoeFrontAt:.7,historyShoeStartYaw:-12,historyShoeEndYaw:-90,historyShoeStartPitch:17,historyShoeEndPitch:18,historyShoeTiltRoll:-12,historyShoeEndRoll:0,historyShoeX:480,historyShoeY:280,historyShoeEndY:140,historyShoeStartSize:240,historyShoeEndSize:1000,historyShoeZoomPower:1.6,historyPaperSpikeLength:.28,historyShoePaperOutline:9,historyShoePaperColor:'#7486a7',historyPaperFoldStart:38.849,historyPaperFoldEnd:40.485,historyPaperFoldStrength:1,historyPaperFinalSize:.19,historyPaperFlightEnd:41.8,historyPaperExitX:-680,historyPaperExitY:-65,historyPaperSpin:130,historyPaperCreaseDepth:125,historyPaperGrid:22,historyPaperIncomingStart:41.2,historyPaperIncomingEnd:42.4};
const clamp=x=>Math.max(0,Math.min(1,x)),lerp=(a,b,q)=>a+(b-a)*q,ease=q=>{q=clamp(q);return q*q*(3-2*q)};
export function shoePaperPose(age,input={}){const f={...shoePaperDefaults,...input},q=clamp((age-f.historyShoeTurnStart)/Math.max(.1,f.historyShoeTurnEnd-f.historyShoeTurnStart)),turn=ease(q/Math.max(.05,f.historyShoeFrontAt)),tilt=q<f.historyShoeTiltEnd?ease(q/Math.max(.01,f.historyShoeTiltEnd)):1-ease((q-f.historyShoeTiltEnd)/Math.max(.01,f.historyShoeFrontAt-f.historyShoeTiltEnd));return {q,yaw:lerp(f.historyShoeStartYaw,f.historyShoeEndYaw,turn),pitch:lerp(f.historyShoeStartPitch,f.historyShoeEndPitch,turn),roll:lerp(0,f.historyShoeEndRoll,turn)+f.historyShoeTiltRoll*tilt,size:lerp(f.historyShoeStartSize,f.historyShoeEndSize,q**Math.max(.2,f.historyShoeZoomPower))};}
export function paperFoldState(age,input={}){const f={...shoePaperDefaults,...input},u=clamp((age-f.historyPaperFoldStart)/Math.max(.1,f.historyPaperFoldEnd-f.historyPaperFoldStart)),q=ease(u),flight=ease((age-f.historyPaperFoldEnd)/Math.max(.1,f.historyPaperFlightEnd-f.historyPaperFoldEnd));return {u,q,flight,scale:lerp(1,Math.max(.06,f.historyPaperFinalSize),q),x:480+f.historyPaperExitX*flight,y:270+f.historyPaperExitY*flight,spin:f.historyPaperSpin*(q*.3+flight)*Math.PI/180};}
export function paintShoePaperBackground(c,images,input={}){const f={...shoePaperDefaults,...input},im=images[f.historySourceBindings?.historyShoePaper||'historyShoePaper'];if(im&&(im.naturalWidth||im.width)){drawAssetMedia(c,im,[0,0,960,540],f,0);return;}c.fillStyle='#aaa79a';c.fillRect(0,0,960,540);}
let rowCanvas,rowKey;
export function paintShoeComposition(c,age,images,input={}){const f={...shoePaperDefaults,...input};paintShoePaperBackground(c,images,f);const travel=Math.max(0,Math.min(age,32)-25.593)*34;for(let i=-2;i<10;i++){if(i===3)continue;const x=i*210+60-travel;if(x< -220||x>1180)continue;const im=f.historyPaperShoeMode==='mesh'?null:images[f.historySourceBindings?.historyShoe||'historyShoe'];if(im&&(im.naturalWidth||im.width)){c.save();c.translate(x,270);c.drawImage(im,-85,-45,170,90);c.restore()}else{const key=String(f.historyShoeColor);if(!rowCanvas||rowKey!==key){rowCanvas=Object.assign(document.createElement('canvas'),{width:960,height:540});const ctx=rowCanvas.getContext('2d'),shoe={id:'restored-row',x:480,y:270,size:170,style:'spikes',upper:f.historyShoeColor||'#232426',accent:'#18191b',sole:'#18191b',yaw:0,pitch:80,roll:0,driftX:0,driftY:0,yawSpeed:0,pitchSpeed:0,rollSpeed:0,spikeLength:0};ctx.shadowColor='#eeeeea';ctx.shadowBlur=4;for(const [dx,dy]of [[-3,0],[3,0],[0,-3],[0,3]]){ctx.save();ctx.translate(dx,dy);paintShoe(ctx,0,shoe);ctx.restore();}ctx.shadowBlur=0;paintShoe(ctx,0,shoe);rowKey=key;}c.drawImage(rowCanvas,x-480,0);}}const p=shoePaperPose(age,f),im=f.historyPaperShoeMode==='mesh'?null:images[f.historySourceBindings?.historyShoe||'historyShoe'];if(im&&(im.naturalWidth||im.width)){c.save();c.translate(f.historyShoeX,lerp(f.historyShoeY,f.historyShoeEndY,ease(p.q)));c.rotate(p.roll*Math.PI/180);const w=p.size,h=w*(im.naturalHeight||im.height)/(im.naturalWidth||im.width);drawAssetMedia(c,im,[-w/2,-h/2,w,h],f,age);c.restore()}else paintSolidShoe(c,{x:f.historyShoeX,y:lerp(f.historyShoeY,f.historyShoeEndY,ease(p.q)),...p,color:f.historyShoeColor,spikeLength:f.historyPaperSpikeLength,outlineWidth:f.historyShoePaperOutline,outline:f.historyShoePaperColor});return p;}
let printCanvas,meshCanvas,printKey,printPixels;
export function paperFoldMesh(age,input={}){const f={...shoePaperDefaults,...input},s=paperFoldState(age,f),N=Math.max(8,Math.min(40,Math.round(f.historyPaperGrid))),M=Math.round(N*540/960),points=[],triangles=[];for(let j=0;j<=M;j++)for(let i=0;i<=N;i++){const u=i/N,v=j/M,X=(u-.5)*960,Y=(v-.5)*540,r=Math.hypot(X/480,Y/270),wave=Math.sin(i*1.83+j*2.37)+.5*Math.cos(i*3.7-j*.91),edge=Math.max(Math.abs(u-.5)*2,Math.abs(v-.5)*2),fold=ease(s.q*1.6-(1-edge)*.45),angle=fold*f.historyPaperFoldStrength*(.8+wave*.38),radial=1-fold*.42,xx0=X*s.scale*radial,yy0=Y*s.scale*radial,zz0=(wave*.6+Math.sin(angle*3+u*9)*.4)*f.historyPaperCreaseDepth*s.q*f.historyPaperFoldStrength;let xx=xx0,yy=yy0,zz=zz0;const blend=ease((s.q-.22)/.78),R=480*f.historyPaperFinalSize*(1+wave*.12),theta=(u-.5)*Math.PI*2,phi=(v-.5)*Math.PI;xx=lerp(xx,Math.sin(theta)*Math.cos(phi)*R,blend);yy=lerp(yy,Math.sin(phi)*R,blend);zz=lerp(zz,Math.cos(theta)*Math.cos(phi)*R+wave*18*f.historyPaperFoldStrength,blend);const cs=Math.cos(s.spin),sn=Math.sin(s.spin),k=1000/(1000-zz);points.push([s.x+(xx*cs-yy*sn)*k,s.y+(xx*sn+yy*cs)*k,zz,u,v])}for(let j=0;j<M;j++)for(let i=0;i<N;i++){const a=j*(N+1)+i,b=a+1,d=a+N+1,e=d+1;for(const ids of [[a,b,e],[a,e,d]]){const p=ids.map(k=>points[k]),A=p[0],B=p[1],C=p[2],ab=B.map((x,k)=>x-A[k]),ac=C.map((x,k)=>x-A[k]),normal=[ab[1]*ac[2]-ab[2]*ac[1],ab[2]*ac[0]-ab[0]*ac[2],ab[0]*ac[1]-ab[1]*ac[0]],len=Math.hypot(...normal)||1,light=.4+.6*Math.abs((normal[0]*-.2+normal[1]*-.35+normal[2]*.92)/len);triangles.push({points:p,shade:lerp(1,light,s.q),untextured:s.q>.1&&normal[2]<0,color:[159,153,137]})}}return {state:s,triangles};}
export function paintPaperCrumple(c,age,images,input={}){const f={...shoePaperDefaults,...input};printCanvas||=Object.assign(document.createElement('canvas'),{width:960,height:540});meshCanvas||=Object.assign(document.createElement('canvas'),{width:960,height:540});const boundPaper=images[f.historySourceBindings?.historyShoePaper||'historyShoePaper'],boundShoe=images[f.historySourceBindings?.historyShoe||'historyShoe'],key=JSON.stringify([f,boundPaper?._assetRevision,boundShoe?._assetRevision]);if(key!==printKey||printCanvas._paper!==boundPaper||printCanvas._shoe!==boundShoe){const p=printCanvas.getContext('2d');paintShoeComposition(p,Math.min(f.historyShoeTurnEnd,f.historyPaperFoldStart),images,f);printPixels={data:p.getImageData(0,0,960,540).data,width:960,height:540};printKey=key;printCanvas._paper=boundPaper;printCanvas._shoe=boundShoe;}paintShoePaperBackground(c,images,f);const mesh=paperFoldMesh(age,f);if(mesh.state.q===0){c.drawImage(printCanvas,0,0);return mesh.state;}putSurface(meshCanvas,rasterSurface(960,540,mesh.triangles,printPixels));c.save();c.shadowColor='#1119';c.shadowBlur=12*mesh.state.q;c.shadowOffsetY=8*mesh.state.q;c.drawImage(meshCanvas,0,0);c.restore();return mesh.state;}
